INSERT INTO `konten` (`id`, `kunci`, `kelompok`, `judul_bagian`, `data_json`, `riwayat_json`, `ringkasan_perubahan`, `updated_at`) VALUES ('4', 'profil_sambutan', 'Beranda', 'Sambutan kepala sekolah', '{"nama_ketua":"Yon Aidil, S.Si","jabatan":"Kepala SMA Swadaya","salam":"Salam sejahtera, saya Kepala Sekolah SMA Swadaya.","kutipan":"“Setiap anak punya potensi. Tugas kami adalah memberi ruang, kesempatan, dan bimbingan agar potensi itu tumbuh.”","isi_sambutan":"Selamat datang di SMA Swadaya. Kami berkomitmen mendidik generasi muda yang berdaya saing melalui kurikulum berbasis praktik nyata, pembentukan karakter mandiri, serta lingkungan belajar yang inklusif dan menyenangkan.","isi_lanjutan":"[Paragraf lanjutan sambutan kepala sekolah]","foto_ketua":""}', '[]', 'Data awal', '2026-11-21 08:00:00');
INSERT INTO `konten` (`id`, `kunci`, `kelompok`, `judul_bagian`, `data_json`, `riwayat_json`, `ringkasan_perubahan`, `updated_at`) VALUES ('5', 'profil_tentang_legalitas', 'Profil', 'Identitas sekolah', '{"hero_judul":"Sekolah yang membentuk siswa mandiri lewat praktik nyata","hero_subjudul":"Kenali sejarah, visi, para pendidik, dan fasilitas yang mendukung belajar siswa SMA Swadaya setiap hari.","akreditasi":"[Akreditasi]","kurikulum":"Kurikulum Merdeka","tahun_berdiri":"[Tahun]","tentang_judul":"Belajar di kelas, studio, dan kebun","tentang_paragraf_1":"SMA Swadaya Bandung memadukan pembelajaran Kurikulum Merdeka dengan praktik langsung. Siswa tidak hanya memahami teori, tetapi juga merancang karya di studio desain grafis, merawat kebun hidroponik, dan bereksperimen di laboratorium sains.","tentang_paragraf_2":"[Sejarah singkat berdirinya SMA Swadaya]","motto":"Unggul, Berkarakter & Berprestasi","foto_gedung":""}', '[]', 'Data awal', '2026-11-21 08:00:00');
INSERT INTO `konten` (`id`, `kunci`, `kelompok`, `judul_bagian`, `data_json`, `riwayat_json`, `ringkasan_perubahan`, `updated_at`) VALUES ('6', 'profil_visi_misi', 'Profil', 'Visi & misi', '{"visi":"Menjadi sekolah yang melahirkan generasi mandiri, berkarakter, dan siap berkarya melalui pembelajaran berbasis praktik nyata.","misi":["Menyelenggarakan pembelajaran Kurikulum Merdeka yang aktif dan berbasis proyek.","Membekali siswa keterampilan nyata di bidang desain, teknologi, dan agrobisnis.","Membentuk kebiasaan disiplin, jujur, dan mandiri dalam keseharian sekolah.","Menciptakan lingkungan belajar yang inklusif, aman, dan menyenangkan."]}', '[]', 'Data awal', '2026-11-21 08:00:00');
