INSERT INTO `konten` (`id`, `kunci`, `kelompok`, `judul_bagian`, `data_json`, `riwayat_json`, `ringkasan_perubahan`, `updated_at`) VALUES ('9', 'data_ekskul', 'Ekstrakurikuler', 'Daftar ekstrakurikuler', '{"hero_judul":"Temukan minat, asah keterampilan","hero_subjudul":"Dari robotika sampai hidroponik, setiap siswa bisa memilih kegiatan yang sesuai minatnya dan belajar langsung dari praktik.","items":[{"nama":"Robotika & Coding Club","kategori":"Teknologi","deskripsi":"Merakit robot sederhana dan belajar pemrograman, dari kode blok sampai Python.","jadwal":"[Hari, jam]","pembina":"[Nama pembina]","foto":"","wajib":false},{"nama":"Desain Grafis & Percetakan","kategori":"Seni & Desain","deskripsi":"Mengolah ide menjadi poster, logo, dan kemasan yang siap dicetak.","jadwal":"[Hari, jam]","pembina":"[Nama pembina]","foto":"","wajib":false},{"nama":"Agrobisnis Hidroponik","kategori":"Sains & Lingkungan","deskripsi":"Menanam sayur di greenhouse sekolah dan belajar memasarkan hasil panen.","jadwal":"[Hari, jam]","pembina":"[Nama pembina]","foto":"","wajib":false},{"nama":"Karya Ilmiah Remaja","kategori":"Sains & Lingkungan","deskripsi":"Meneliti masalah di sekitar sekolah dan menyusun laporan ilmiah sederhana.","jadwal":"[Hari, jam]","pembina":"[Nama pembina]","foto":"","wajib":false},{"nama":"Pramuka","kategori":"Karakter","deskripsi":"Melatih kemandirian, kerja sama, dan kepemimpinan melalui kegiatan kepramukaan.","jadwal":"[Hari, jam]","pembina":"[Nama pembina]","foto":"","wajib":true},{"nama":"Jurnalistik & Konten Kreatif","kategori":"Seni & Desain","deskripsi":"Meliput kegiatan sekolah dan mengelola konten media sosial sekolah.","jadwal":"[Hari, jam]","pembina":"[Nama pembina]","foto":"","wajib":false},{"nama":"Futsal","kategori":"Olahraga","deskripsi":"Latihan teknik dasar, strategi tim, dan persiapan turnamen antarsekolah.","jadwal":"[Hari, jam]","pembina":"[Nama pembina]","foto":"","wajib":false},{"nama":"Paduan Suara","kategori":"Seni & Desain","deskripsi":"Berlat